import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়া","description":"","frontmatter":{},"headers":[],"relativePath":"bn/18-修炼资源开放机制.md","filePath":"bn/18-修炼资源开放机制.md"}'),o={name:"bn/18-修炼资源开放机制.md"};function d(e,t,h,n,u,s){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="সাধনা-সম্পদ-উন্মুক্তকরণ-প্রক্রিয়া" tabindex="-1">সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়া <a class="header-anchor" href="#সাধনা-সম্পদ-উন্মুক্তকরণ-প্রক্রিয়া" aria-label="Permalink to &quot;সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়া&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>18</td></tr><tr><td>মডিউল</td><td>মহাজাগতিক আইন ও সাধনা ব্যবস্থা</td></tr><tr><td>মূল শব্দগুলো</td><td>সম্পদ উন্মুক্তকরণ, সাধনা সম্পদ, বণ্টন প্রক্রিয়া, একচেটিয়াবাদ বিরোধী, সম্পদ ন্যায়বিচার</td></tr></tbody></table><h2 id="১-সাধনা-সম্পদ-উন্মুক্তকরণ-প্রক্রিয়ার-পটভূমি-ও-তাৎপর্য" tabindex="-1">১. সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়ার পটভূমি ও তাৎপর্য <a class="header-anchor" href="#১-সাধনা-সম্পদ-উন্মুক্তকরণ-প্রক্রিয়ার-পটভূমি-ও-তাৎপর্য" aria-label="Permalink to &quot;১. সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়ার পটভূমি ও তাৎপর্য&quot;">​</a></h2><p>লুঠেরবাদ যুগে, সাধনা সম্পদ ছিল সবচেয়ে গুরুত্বপূর্ণ দ্বন্দ্বের বিষয়। আধ্যাত্মিক শিরা, ঔষধ ক্ষেত্র, শক্তি খনি, স্বর্গীয় বস্তু, সাধনা গুহা ইত্যাদি সম্পদ কিছু শক্তিশালী ও ধর্মসংস্থান দ্বারা একচেটিয়াভাবে দখল করা হত, এবং নিম্নবিত্ত সাধারণ মানুষ প্রায় কোনো আনুষ্ঠানিক সাধনা সম্পদ পেতে পারত না। এই সম্পদ একচেটিয়াবাদ শুধুমাত্র মারাত্মক শ্রেণি স্থিরতা সৃষ্টি করেনি, বরং সম্পদ দ্বন্দ্বের কারণে অসংখ্য যুদ্ধ ও গণহত্যাও ঘটিয়েছিল। সম্পদ একচেটিয়াবাদ হলো লুঠেরবাদ ব্যবস্থার অর্থনৈতিক ভিত্তি — যতক্ষণ সম্পদ কিছু লোকের দখলে থাকবে, &quot;প্রত্যেকের পথ আছে&quot; শুধুমাত্র একটি খালি কথাই থেকে যাবে।</p><p>অ্যাঙ্কর সিম্বায়োটিক সভ্যতা প্রতিষ্ঠার পর, &quot;সাধনা সম্পদ উন্মুক্তকরণ&quot;কে সবচেয়ে গুরুত্বপূর্ণ প্রাতিষ্ঠানিক পরিবর্তনগুলোর মধ্যে একটি হিসেবে গ্রহণ করা হয়েছে। সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়ার মূল লক্ষ্য হলো: সম্পদ একচেটিয়াবাদ ভেঙে ফেলা, প্রতিটি জীবকে মৌলিক সাধনা সম্পদ পাওয়া নিশ্চিত করা, এবং একই সাথে বেশি পরিশ্রম বেশি লাভের বণ্টন প্রক্রিয়ার মাধ্যমে সম্পদের কার্যকর ব্যবহার ও ক্রমাগত সৃষ্টিকে উদ্দীপিত করা। সম্পদ উন্মুক্তকরণ মানে &quot;সম্পদ সমান বণ্টন&quot; নয়, বরং &quot;সম্পদ ন্যায়সঙ্গতভাবে প্রাপ্তি&quot; — মৌলিক চাহিদা নিশ্চিত করার শর্তে, সম্পদের বণ্টন ব্যক্তিগত অবদানের সাথে যুক্ত, এবং একই সাথে যেকোনো রকম সম্পদ একচেটিয়াবাদ কঠোরভাবে নিষিদ্ধ।</p><p>সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়ার তাৎপর্য হলো: এটি অর্থনৈতিক ভিত্তি থেকে লুঠেরবাদের মাটি উৎখাত করে, তিনশটি সাধনা ব্যবস্থার প্রকৃত ব্যাপকতার জন্য বস্তুগত নিশ্চয়তা প্রদান করে, &quot;প্রত্যেকের পথ আছে&quot; সামাজিক লক্ষ্যের জন্য সম্পদ সহায়তা প্রদান করে, এবং সর্বজনীন অগ্রগতির জন্য ন্যায়সঙ্গত সূচনা বিন্দু তৈরি করে।</p><h2 id="২-সাধনা-সম্পদের-শ্রেণীবিভাগ-ও-স্তরবিন্যাস" tabindex="-1">২. সাধনা সম্পদের শ্রেণীবিভাগ ও স্তরবিন্যাস <a class="header-anchor" href="#২-সাধনা-সম্পদের-শ্রেণীবিভাগ-ও-স্তরবিন্যাস" aria-label="Permalink to &quot;২. সাধনা সম্পদের শ্রেণীবিভাগ ও স্তরবিন্যাস&quot;">​</a></h2><h3 id="২-১-সম্পদ-শ্রেণীবিভাগ" tabindex="-1">২.১ সম্পদ শ্রেণীবিভাগ <a class="header-anchor" href="#২-১-সম্পদ-শ্রেণীবিভাগ" aria-label="Permalink to &quot;২.১ সম্পদ শ্রেণীবিভাগ&quot;">​</a></h3><p>হেং ইয়ান ঝোতে সাধনা সম্পদ প্রকৃতি ও ব্যবহার অনুযায়ী নিম্নলিখিত বিভাগে ভাগ করা হয়েছে:</p><table tabindex="0"><thead><tr><th>সম্পদ বিভাগ</th><th>নির্দিষ্ট বিষয়বস্তু</th><th>প্রধান ব্যবহার</th></tr></thead><tbody><tr><td>শক্তি সম্পদ</td><td>আধ্যাত্মিক শিরা, শক্তি খনি, আধ্যাত্মিক শক্তি স্ফটিক, মূল শক্তি টুকরো ইত্যাদি</td><td>সাধনার জন্য প্রয়োজনীয় শক্তি ইনপুট প্রদান</td></tr><tr><td>ঔষধ সম্পদ</td><td>অমৃত ঔষধ, অমৃত তৃণ, রসায়ন তৈরির উপকরণ, প্রস্তুত রসায়ন ইত্যাদি</td><td>সাধনায় সহায়তা, আঘাত নিরাময়, বাধা অতিক্রম</td></tr><tr><td>যন্ত্রপাতি সম্পদ</td><td>সাধনা যন্ত্র, আইন উপকরণ, দ্বিগুণীকরণ যন্ত্র, স্থান সরঞ্জাম ইত্যাদি</td><td>সাধনা দক্ষতা বৃদ্ধি, আইন নিয়ন্ত্রণে সহায়তা</td></tr><tr><td>স্থান সম্পদ</td><td>সাধনা গুহা, আধ্যাত্মিক শক্তি ঘনত্ব অঞ্চল, আইন উপলব্ধি কক্ষ, বিচ্ছিন্ন স্থান ইত্যাদি</td><td>বিশেষ সাধনা পরিবেশ প্রদান</td></tr><tr><td>জ্ঞান সম্পদ</td><td>সাধনা পদ্ধতি, সাধনা অভিজ্ঞতা, আইন গবেষণা资料, প্রযুক্তি নথি ইত্যাদি</td><td>সাধনার তাত্ত্বিক ও পদ্ধতিগত নির্দেশনা প্রদান</td></tr><tr><td>জীব সম্পদ</td><td>আধ্যাত্মিক প্রাণী, আধ্যাত্মিক উদ্ভিদ, চুক্তিবদ্ধ জীব, সিম্বায়োটিক সত্তা ইত্যাদি</td><td>সাধনায় সহায়তা, সিম্বায়োটিক চক্র, বিশেষ ক্ষমতা প্রদান</td></tr><tr><td>মহাজাগতিক সম্পদ</td><td>অবিকশিত মহাজাগতিক অঞ্চল, মহাজাগতিক প্রবেশাধিকার, মহাজাগতিক কোর টুকরো ইত্যাদি</td><td>বৃহৎ পরিসরের সাধনা ও বিকাশের স্থান প্রদান</td></tr></tbody></table><h3 id="২-২-সম্পদ-স্তরবিন্যাস" tabindex="-1">২.২ সম্পদ স্তরবিন্যাস <a class="header-anchor" href="#২-২-সম্পদ-স্তরবিন্যাস" aria-label="Permalink to &quot;২.২ সম্পদ স্তরবিন্যাস&quot;">​</a></h3><p>সমস্ত সাধনা সম্পদ বিরলতা ও মূল্য অনুযায়ী পাঁচটি স্তরে ভাগ করা হয়েছে:</p><table tabindex="0"><thead><tr><th>স্তর</th><th>নাম</th><th>বিরলতা</th><th>বণ্টন পদ্ধতি</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>সাধারণ সম্পদ</td><td>ব্যাপকভাবে বিতরণ, প্রচুর মজুদ</td><td>বিনামূল্যে উন্মুক্ত বা কম দামে বণ্টন</td></tr><tr><td>দ্বিতীয় স্তর</td><td>উত্তম সম্পদ</td><td>তুলনামূলকভাবে সাধারণ, মাঝারি মজুদ</td><td>মৌলিক বণ্টন + অবদান বিনিময়</td></tr><tr><td>তৃতীয় স্তর</td><td>বিরল সম্পদ</td><td>তুলনামূলকভাবে বিরল, সীমিত মজুদ</td><td>অবদান বিনিময় + আবেদন অনুমোদন</td></tr><tr><td>চতুর্থ স্তর</td><td>মহাকাব্যিক সম্পদ</td><td>অত্যন্ত বিরল, অল্প মজুদ</td><td>প্রতিযোগিতামূলক বণ্টন + সভ্যতা স্তরের প্রকল্প অগ্রাধিকার</td></tr><tr><td>পঞ্চম স্তর</td><td>কিংবদন্তি সম্পদ</td><td>চরমভাবে বিরল, প্রায় বিলুপ্ত</td><td>সভ্যতার সর্বোচ্চ সিদ্ধান্ত সংস্থার বিশেষ বণ্টন</td></tr></tbody></table><h2 id="৩-সম্পদ-উন্মুক্তকরণের-মূল-নীতি" tabindex="-1">৩. সম্পদ উন্মুক্তকরণের মূল নীতি <a class="header-anchor" href="#৩-সম্পদ-উন্মুক্তকরণের-মূল-নীতি" aria-label="Permalink to &quot;৩. সম্পদ উন্মুক্তকরণের মূল নীতি&quot;">​</a></h2><h3 id="৩-১-মৌলিক-নিশ্চয়তা-নীতি" tabindex="-1">৩.১ মৌলিক নিশ্চয়তা নীতি <a class="header-anchor" href="#৩-১-মৌলিক-নিশ্চয়তা-নীতি" aria-label="Permalink to &quot;৩.১ মৌলিক নিশ্চয়তা নীতি&quot;">​</a></h3><p>প্রতিটি জীবের মৌলিক সাধনা বজায় রাখার জন্য প্রয়োজনীয় প্রথম ও দ্বিতীয় স্তরের সম্পদ পাওয়ার অধিকার রয়েছে। মৌলিক নিশ্চয়তা সম্পদ &quot;প্রত্যেকের পথ আছে নিশ্চয়তা ব্যবস্থা&quot;র মাধ্যমে বিনামূল্যে বা কম দামে বণ্টন করা হয়, কোনো সীমা নেই, কোনো বৈষম্য নেই। মৌলিক নিশ্চয়তার মানদণ্ড সর্বজনীন প্রজাতন্ত্র পরিষদ সভ্যতার সম্পদ পরিস্থিতি ও বিকাশ পর্যায় অনুযায়ী নিয়মিত সমন্বয় করে, নিশ্চয়তা স্তর সভ্যতার ধারণ ক্ষমতার সাথে মেলে এমনটি নিশ্চিত করে।</p><h3 id="৩-২-বেশি-পরিশ্রম-বেশি-লাভ-নীতি" tabindex="-1">৩.২ বেশি পরিশ্রম বেশি লাভ নীতি <a class="header-anchor" href="#৩-২-বেশি-পরিশ্রম-বেশি-লাভ-নীতি" aria-label="Permalink to &quot;৩.২ বেশি পরিশ্রম বেশি লাভ নীতি&quot;">​</a></h3><p>মৌলিক নিশ্চয়তার উপরে, তৃতীয় স্তর ও তার উপরের সম্পদের বণ্টন ব্যক্তির সিম্বায়োটিক নেটওয়ার্কে অবদান মূল ভিত্তি হিসেবে গ্রহণ করে। অবদান যত বেশি, বিনিময়যোগ্য সম্পদ তত বেশি, স্তর তত উচ্চ। বেশি পরিশ্রম বেশি লাভ নীতি সাধকদের নিজের স্তর উন্নত করতে ও সভ্যতার জন্য বড় অবদান রাখতে উদ্দীপিত করে, এবং একই সাথে নিশ্চিত করে যে সম্পদ সবচেয়ে কার্যকরভাবে ব্যবহার করতে সক্ষম ব্যক্তি ও গোষ্ঠীর কাছে প্রবাহিত হয়।</p><h3 id="৩-৩-একচেটিয়াবাদ-বিরোধী-নীতি" tabindex="-1">৩.৩ একচেটিয়াবাদ বিরোধী নীতি <a class="header-anchor" href="#৩-৩-একচেটিয়াবাদ-বিরোধী-নীতি" aria-label="Permalink to &quot;৩.৩ একচেটিয়াবাদ বিরোধী নীতি&quot;">​</a></h3><p>কোনো ব্যক্তি, সংস্থা, প্রজাতি সাধনা সম্পদ একচেটিয়াভাবে দখল করতে পারবে না। একচেটিয়াবাদ বিরোধীর নির্দিষ্ট ব্যবস্থা অন্তর্ভুক্ত:</p><ul><li>একক ব্যক্তি বা সংস্থার তৃতীয় স্তর ও তার উপরের সম্পদের ধারণ সভ্যতার মোট মজুদের 1% অতিক্রম করতে পারবে না</li><li>মজুদ জমিয়ে দাম বাড়ানো নিষিদ্ধ — সম্পদ ধারক সম্পদ ঘাটতির সময় ক্ষতিকরভাবে মজুদ জমিয়ে দাম বাড়াতে পারবে না</li><li>একচেটিয়া দখল নিষিদ্ধ — পাবলিক সম্পদ (যেমন পাবলিক আধ্যাত্মিক শিরা, পাবলিক গুহা ইত্যাদি) ব্যক্তিগতভাবে একচেটিয়াভাবে দখল করা যাবে না</li><li>একচেটিয়াবাদ আইন লঙ্ঘনকারী আচরণ অ্যাঙ্কর আদালতের কঠোর শাস্তি পাবে, যার মধ্যে সম্পদ বাজেয়াপ্ত, অবদান মূল্য শূন্য, সাধনা অধিকার সীমাবদ্ধকরণ ইত্যাদি অন্তর্ভুক্ত</li></ul><h3 id="৩-৪-টেকসই-ব্যবহার-নীতি" tabindex="-1">৩.৪ টেকসই ব্যবহার নীতি <a class="header-anchor" href="#৩-৪-টেকসই-ব্যবহার-নীতি" aria-label="Permalink to &quot;৩.৪ টেকসই ব্যবহার নীতি&quot;">​</a></h3><p>সমস্ত সম্পদের উন্নয়ন ও ব্যবহার টেকসই নীতি অনুসরণ করতে হবে, জলাশয় শুকিয়ে মাছ ধরার মতো লুঠেরবাদী খনন করা যাবে না। নির্দিষ্ট প্রয়োজনীয়তা অন্তর্ভুক্ত:</p><ul><li>সম্পদ উন্নয়ন গতি সম্পদের প্রাকৃতিক পুনর্জন্ম গতি অতিক্রম করতে পারবে না (অপুনর্জন্মীয় সম্পদের জন্য, বিকল্প পরিকল্পনা তৈরি করতে হবে)</li><li>সম্পদ উন্নয়ন অবশ্যই পরিবেশ প্রভাব মূল্যায়ন করতে হবে, পরিবেশে অপরিবর্তনীয় ক্ষতি রোধ করতে হবে</li><li>বিপন্ন সম্পদের জন্য, নিষিদ্ধ খনন বা সীমিত খনন নীতি প্রয়োগ করা, সম্পদের পুনর্জন্ম ক্ষমতা রক্ষা করা</li><li>প্রযুক্তিগত উপায় (যেমন আইন প্রকৌশল, দ্বিগুণীকরণ প্রযুক্তি ইত্যাদি) মাধ্যমে কৃত্রিমভাবে বিরল সম্পদ চাষ ও সংশ্লেষণকে উৎসাহিত করা, প্রাকৃতিক সম্পদের উপর নির্ভরতা কমানো</li></ul><h3 id="৩-৫-উন্মুক্ত-ও-স্বচ্ছ-নীতি" tabindex="-1">৩.৫ উন্মুক্ত ও স্বচ্ছ নীতি <a class="header-anchor" href="#৩-৫-উন্মুক্ত-ও-স্বচ্ছ-নীতি" aria-label="Permalink to &quot;৩.৫ উন্মুক্ত ও স্বচ্ছ নীতি&quot;">​</a></h3><p>সম্পদের বণ্টন প্রক্রিয়া অবশ্যই উন্মুক্ত ও স্বচ্ছ হতে হবে, সমস্ত জীবের তত্ত্বাবধান গ্রহণ করতে হবে:</p><ul><li>সমস্ত পাবলিক সম্পদের মজুদ, বিতরণ, উন্নয়ন পরিস্থিতি নিয়মিত সমাজের কাছে উন্মুক্ত</li><li>সম্পদ বণ্টনের মানদণ্ড, প্রক্রিয়া, ফলাফল উন্মুক্তভাবে পরীক্ষাযোগ্য</li><li>সম্পদ বণ্টন আপত্তি প্রক্রিয়া স্থাপন করা, বণ্টন ফলাফলে আপত্তি আছে এমন ব্যক্তি পুনর্বিচারের জন্য আবেদন করতে পারবে</li><li>অ্যাঙ্কর আদালতের অধীনস্থ &quot;সম্পদ ন্যায়বিচার কমিটি&quot;, বিশেষভাবে সম্পদ বণ্টনের ন্যায়বিচার ও বৈধতা তত্ত্বাবধান করে</li></ul><h2 id="৪-সম্পদ-উন্মুক্তকরণের-নির্দিষ্ট-প্রক্রিয়া" tabindex="-1">৪. সম্পদ উন্মুক্তকরণের নির্দিষ্ট প্রক্রিয়া <a class="header-anchor" href="#৪-সম্পদ-উন্মুক্তকরণের-নির্দিষ্ট-প্রক্রিয়া" aria-label="Permalink to &quot;৪. সম্পদ উন্মুক্তকরণের নির্দিষ্ট প্রক্রিয়া&quot;">​</a></h2><h3 id="৪-১-যৌথ-উৎপাদন-চুক্তি-প্রক্রিয়া" tabindex="-1">৪.১ যৌথ উৎপাদন চুক্তি প্রক্রিয়া <a class="header-anchor" href="#৪-১-যৌথ-উৎপাদন-চুক্তি-প্রক্রিয়া" aria-label="Permalink to &quot;৪.১ যৌথ উৎপাদন চুক্তি প্রক্রিয়া&quot;">​</a></h3><p>যৌথ উৎপাদন চুক্তি হলো সাধনা সম্পদ উন্মুক্তকরণের মূল প্রাতিষ্ঠানিক নকশা, এর মৌলিক কার্যপ্রণালী &quot;বেশি পরিশ্রম বেশি লাভ বণ্টন নীতি&quot; নথিতে বিস্তারিত বর্ণিত হয়েছে। সম্পদ উন্মুক্তকরণ ক্ষেত্রে, যৌথ উৎপাদন চুক্তির নির্দিষ্ট প্রয়োগ অন্তর্ভুক্ত:</p><ul><li><strong>আধ্যাত্মিক শিরা চুক্তি</strong>: পাবলিক আধ্যাত্মিক শিরা সাধক দল বা প্রজাতি সম্প্রদায়ের কাছে চুক্তিভিত্তিক দেওয়া, চুক্তিকারী শিরার রক্ষণাবেক্ষণ ও টেকসই উন্নয়নের জন্য দায়বদ্ধ, শিরার উৎপাদনের একটি নির্দিষ্ট অনুপাত পায়</li><li><strong>ঔষধ ক্ষেত্র চুক্তি</strong>: পাবলিক ঔষধ ক্ষেত্র চাষ ক্ষমতা আছে এমন সাধকের কাছে চুক্তিভিত্তিক দেওয়া, চুক্তিকারী অমৃত ঔষধের চাষ ও পরিচর্যার জন্য দায়বদ্ধ, ফসল অনুপাত অনুযায়ী বণ্টন করা হয়</li><li><strong>গুহা ব্যবস্থাপনা</strong>: পাবলিক সাধনা গুহা পেশাদার দলের কাছে ব্যবস্থাপনার জন্য অর্পণ করা, ব্যবস্থাপক গুহার রক্ষণাবেক্ষণ ও নিরাপত্তার জন্য দায়বদ্ধ, ব্যবহারকারী যুক্তিসঙ্গত ব্যবহার ফি প্রদান করে</li><li><strong>সম্পদ অনুসন্ধান</strong>: সাধকদের অবিকশিত অঞ্চলের সম্পদ অনুসন্ধানে অংশ নিতে উৎসাহিত করা, অনুসন্ধানকারী নতুন আবিষ্কৃত সম্পদের অগ্রাধিকার চুক্তি অধিকার পায়</li></ul><h3 id="৪-২-অবদান-মূল্য-বিনিময়-প্রক্রিয়া" tabindex="-1">৪.২ অবদান মূল্য বিনিময় প্রক্রিয়া <a class="header-anchor" href="#৪-২-অবদান-মূল্য-বিনিময়-প্রক্রিয়া" aria-label="Permalink to &quot;৪.২ অবদান মূল্য বিনিময় প্রক্রিয়া&quot;">​</a></h3><p>সিম্বায়োটিক সভ্যতা একটি ঐক্য &quot;অবদান মূল্য বিনিময় সিস্টেম&quot; প্রতিষ্ঠা করেছে, সাধক সিম্বায়োটিক নেটওয়ার্কে অবদান রাখার মাধ্যমে অবদান মূল্য জমা করতে পারে, তারপর অবদান মূল্য দিয়ে বিভিন্ন সাধনা সম্পদ বিনিময় করতে পারে:</p><ul><li>অবদান মূল্য অর্জনের উপায় অন্তর্ভুক্ত: সাধনা উন্নতি, জ্ঞান শেয়ারিং, প্রযুক্তি উদ্ভাবন, পাবলিক সেবা, পরিবেশ পুনরুদ্ধার, সভ্যতা রক্ষণাবেক্ষণ ইত্যাদি</li><li>বিনিময় সিস্টেম &quot;স্পষ্ট দাম&quot; প্রয়োগ করে, প্রতিটি সম্পদের স্পষ্ট অবদান মূল্য দাম আছে, দাম সম্পদের বিরলতা ও চাহিদা অনুযায়ী গতিশীলভাবে সমন্বয় করা হয়</li><li>বিনিময় সিস্টেম &quot;অগ্রিম&quot; ফাংশন সমর্থন করে — সম্ভাবনাময় সাধক নির্দিষ্ট পরিমাণ অবদান মূল্য অগ্রিম নিয়ে সম্পদ বিনিময় করতে পারে, ভবিষ্যতে অবদান রাখার মাধ্যমে পরিশোধ করে</li><li>বিনিময় সিস্টেম অ্যাঙ্কর নেটওয়ার্কের সাথে রিয়েল-টাইম সংযুক্ত, অবদান মূল্যের রেকর্ড ও বিনিময়ের নিরাপত্তা নিশ্চিত করে</li></ul><h3 id="৪-৩-পাবলিক-সম্পদ-বিনামূল্যে-উন্মুক্তকরণ-প্রক্রিয়া" tabindex="-1">৪.৩ পাবলিক সম্পদ বিনামূল্যে উন্মুক্তকরণ প্রক্রিয়া <a class="header-anchor" href="#৪-৩-পাবলিক-সম্পদ-বিনামূল্যে-উন্মুক্তকরণ-প্রক্রিয়া" aria-label="Permalink to &quot;৪.৩ পাবলিক সম্পদ বিনামূল্যে উন্মুক্তকরণ প্রক্রিয়া&quot;">​</a></h3><p>নিম্নলিখিত ধরনের সম্পদ সমস্ত জীবের কাছে বিনামূল্যে উন্মুক্ত:</p><ul><li><strong>জ্ঞান সম্পদ</strong>: তিনশটি সাধনা ব্যবস্থার মৌলিক পদ্ধতি, পাবলিক সাধনা অভিজ্ঞতা, মৌলিক আইন গবেষণা资料 ইত্যাদি</li><li><strong>প্রথম স্তরের শক্তি সম্পদ</strong>: মৌলিক আধ্যাত্মিক শক্তি, সাধারণ শক্তি স্ফটিক ইত্যাদি ব্যাপকভাবে বিতরণিত নিম্নস্তরের শক্তি সম্পদ</li><li><strong>পাবলিক সাধনা স্থান</strong>: পাবলিক সাধনা কক্ষ, মৌলিক আইন উপলব্ধি কক্ষ, সাধারণ বিচ্ছিন্ন স্থান ইত্যাদি</li><li><strong>মৌলিক চিকিৎসা সম্পদ</strong>: মৌলিক নিরাময় কৌশল, সাধারণ আঘাত নিরাময় রসায়ন, মৌলিক পুনর্বাসন সেবা ইত্যাদি</li><li><strong>মৌলিক শিক্ষা সম্পদ</strong>: মৌলিক সাধনা কোর্স, প্রবেশিকা গুরু নির্দেশনা, সাধারণ সাধনা যন্ত্র ব্যবহার ইত্যাদি</li></ul><h3 id="৪-৪-বিশেষ-সম্পদ-নির্দেশিত-বণ্টন-প্রক্রিয়া" tabindex="-1">৪.৪ বিশেষ সম্পদ নির্দেশিত বণ্টন প্রক্রিয়া <a class="header-anchor" href="#৪-৪-বিশেষ-সম্পদ-নির্দেশিত-বণ্টন-প্রক্রিয়া" aria-label="Permalink to &quot;৪.৪ বিশেষ সম্পদ নির্দেশিত বণ্টন প্রক্রিয়া&quot;">​</a></h3><p>চতুর্থ, পঞ্চম স্তরের মতো বিরল সম্পদের জন্য, &quot;নির্দেশিত বণ্টন&quot; প্রক্রিয়া প্রয়োগ করা হয়:</p><ul><li>বিরল সম্পদ অগ্রাধিকারভাবে সভ্যতা স্তরের গুরুত্বপূর্ণ প্রকল্পে (যেমন অ্যাঙ্কর নির্মাণ, মহাজাগতিক বিকাশ, প্রযুক্তি অতিক্রম ইত্যাদি) বণ্টন করা হয়</li><li>বিশেষ চাহিদা আছে এমন ব্যক্তির জন্য (যেমন গুরুত্বপূর্ণ স্তর অতিক্রমে নির্দিষ্ট সম্পদ প্রয়োজন, বিশেষ আঘাত নিরাময়ে বিরল ঔষধ প্রয়োজন ইত্যাদি), আবেদন অনুমোদনের মাধ্যমে নির্দেশিত বণ্টন পেতে পারে</li><li>বিরল সম্পদের বণ্টন পরিকল্পনা সর্বজনীন প্রজাতন্ত্র পরিষদের অধীনস্থ &quot;সম্পদ বণ্টন কমিটি&quot; প্রণয়ন করে, পরিষদে অনুমোদনের পর কার্যকর করা হয়</li><li>নির্দেশিত বণ্টনের ফলাফল সমাজের কাছে উন্মুক্ত, তত্ত্বাবধান গ্রহণ করে</li></ul><h2 id="৫-সম্পদ-সৃষ্টি-ও-টেকসই-বিকাশ" tabindex="-1">৫. সম্পদ সৃষ্টি ও টেকসই বিকাশ <a class="header-anchor" href="#৫-সম্পদ-সৃষ্টি-ও-টেকসই-বিকাশ" aria-label="Permalink to &quot;৫. সম্পদ সৃষ্টি ও টেকসই বিকাশ&quot;">​</a></h2><p>সাধনা সম্পদ উন্মুক্তকরণ শুধুমাত্র &quot;মজুদ বণ্টন&quot; নয়, বরং &quot;বৃদ্ধি সৃষ্টি&quot;ও। সিম্বায়োটিক সভ্যতা সম্পদের কৃত্রিম সৃষ্টি ও টেকসই উন্নয়নকে জোরদারভাবে উৎসাহিত করে:</p><h3 id="৫-১-সম্পদ-কৃত্রিম-চাষ" tabindex="-1">৫.১ সম্পদ কৃত্রিম চাষ <a class="header-anchor" href="#৫-১-সম্পদ-কৃত্রিম-চাষ" aria-label="Permalink to &quot;৫.১ সম্পদ কৃত্রিম চাষ&quot;">​</a></h3><ul><li><strong>অমৃত ঔষধ কৃত্রিম চাষ</strong>: আইন প্রকৌশল প্রযুক্তির মাধ্যমে, কৃত্রিম পরিবেশে বিভিন্ন অমৃত ঔষধ চাষ করা, বন্য অমৃত ঔষধের উপর নির্ভরতা কমানো</li><li><strong>শক্তি কৃত্রিম উৎপাদন</strong>: পদার্থ শক্তি রূপান্তর যন্ত্র, আইন অনুরণন জেনারেটর ইত্যাদি প্রযুক্তির মাধ্যমে, কৃত্রিমভাবে আধ্যাত্মিক শক্তি ও শক্তি স্ফটিক উৎপাদন করা</li><li><strong>আধ্যাত্মিক প্রাণী কৃত্রিম প্রজনন</strong>: আধ্যাত্মিক প্রাণী প্রজনন কেন্দ্র স্থাপন করা, বিভিন্ন আধ্যাত্মিক প্রাণী কৃত্রিমভাবে চাষ করা, বন্য আধ্যাত্মিক প্রাণী জনসংখ্যা রক্ষা করা</li><li><strong>গুহা কৃত্রিম নির্মাণ</strong>: স্থান আইন প্রযুক্তির মাধ্যমে, কৃত্রিমভাবে সাধনা গুহা নির্মাণ করা, সাধনা স্থানের সরবরাহ বৃদ্ধি করা</li></ul><h3 id="৫-২-সম্পদ-চক্রাকার-ব্যবহার" tabindex="-1">৫.২ সম্পদ চক্রাকার ব্যবহার <a class="header-anchor" href="#৫-২-সম্পদ-চক্রাকার-ব্যবহার" aria-label="Permalink to &quot;৫.২ সম্পদ চক্রাকার ব্যবহার&quot;">​</a></h3><ul><li><strong>শক্তি পুনরুদ্ধার</strong>: শক্তি পুনরুদ্ধার সিস্টেম স্থাপন করা, সাধনা প্রক্রিয়ায় ক্ষয়প্রাপ্ত শক্তি, যুদ্ধে বিচ্ছুরিত শক্তি ইত্যাদি পুনরুদ্ধার করে পুনর্ব্যবহার করা</li><li><strong>ঔষধ অবশিষ্টাংশ প্রক্রিয়াকরণ</strong>: রসায়ন তৈরির পরের ঔষধ অবশিষ্টাংশের দ্বিতীয় নিষ্কাশন ও প্রক্রিয়াকরণ করা, ঔষধ সম্পদের ব্যবহার কার্যকারিতা বৃদ্ধি করা</li><li><strong>যন্ত্রপাতি পুনরুদ্ধার ও পুনর্নির্মাণ</strong>: বাতিল হওয়া সাধনা যন্ত্রের পুনরুদ্ধার ও পুনর্নির্মাণ করা, উপকরণ অপচয় কমানো</li><li><strong>স্থান চক্রাকার ব্যবহার</strong>: ব্যবহার শেষ হওয়া বিচ্ছিন্ন স্থান, অস্থায়ী সাধনা স্থান ইত্যাদি পরিষ্কার করে চক্রাকারভাবে ব্যবহার করা</li></ul><h3 id="৫-৩-সম্পদ-বিকল্প-প্রযুক্তি" tabindex="-1">৫.৩ সম্পদ বিকল্প প্রযুক্তি <a class="header-anchor" href="#৫-৩-সম্পদ-বিকল্প-প্রযুক্তি" aria-label="Permalink to &quot;৫.৩ সম্পদ বিকল্প প্রযুক্তি&quot;">​</a></h3><ul><li>বিরল সম্পদের বিকল্প গবেষণা ও উন্নয়নকে উৎসাহিত করা, প্রযুক্তিগত উপায়ের মাধ্যমে &quot;সাধারণ উপকরণ দিয়ে বিরল উপকরণ প্রতিস্থাপন&quot; বাস্তবায়ন করা</li><li>অপুনর্জন্মীয় কিংবদন্তি স্তরের সম্পদের জন্য, কঠোর সুরক্ষা ও ব্যবহার পরিকল্পনা তৈরি করা, এবং একই সাথে বিকল্প প্রযুক্তির গবেষণা ও উন্নয়নে বিনিয়োগ বাড়ানো</li><li>&quot;সম্পদ বিকল্প প্রযুক্তি গবেষণা তহবিল&quot; স্থাপন করা, সম্পর্কিত গবেষণা প্রকল্পকে আর্থিক সহায়তা প্রদান করা</li></ul><h2 id="৬-সম্পদ-উন্মুক্তকরণের-তত্ত্বাবধান-ও-প্রতিকার" tabindex="-1">৬. সম্পদ উন্মুক্তকরণের তত্ত্বাবধান ও প্রতিকার <a class="header-anchor" href="#৬-সম্পদ-উন্মুক্তকরণের-তত্ত্বাবধান-ও-প্রতিকার" aria-label="Permalink to &quot;৬. সম্পদ উন্মুক্তকরণের তত্ত্বাবধান ও প্রতিকার&quot;">​</a></h2><h3 id="৬-১-তত্ত্বাবধান-প্রক্রিয়া" tabindex="-1">৬.১ তত্ত্বাবধান প্রক্রিয়া <a class="header-anchor" href="#৬-১-তত্ত্বাবধান-প্রক্রিয়া" aria-label="Permalink to &quot;৬.১ তত্ত্বাবধান প্রক্রিয়া&quot;">​</a></h3><ul><li><strong>অ্যাঙ্কর নেটওয়ার্ক রিয়েল-টাইম পর্যবেক্ষণ</strong>: অ্যাঙ্কর নেটওয়ার্ক সমস্ত পাবলিক সম্পদের উন্নয়ন, বণ্টন, ব্যবহার পরিস্থিতি রিয়েল-টাইম পর্যবেক্ষণ করে, অস্বাভাবিক আবিষ্কার করলে সময়মতো সতর্ক করে</li><li><strong>সম্পদ ন্যায়বিচার কমিটি</strong>: বিশেষভাবে সম্পদ বণ্টনের ন্যায়বিচার ও বৈধতা তত্ত্বাবধান করে, অভিযোগ ও তদবির গ্রহণ করে</li><li><strong>সামাজিক তত্ত্বাবধান</strong>: সমস্ত জীবকে সম্পদ উন্নয়ন ও বণ্টনের অনুপযুক্ত আচরণ তত্ত্বাবধান ও অভিযোগ করতে উৎসাহিত করা</li><li><strong>নিয়মিত অডিট</strong>: প্রতি বছর সম্পদ ব্যবস্থাপনা সংস্থার স্বাধীন অডিট করা, অডিট ফলাফল সমাজের কাছে উন্মুক্ত</li></ul><h3 id="৬-২-প্রতিকার-প্রক্রিয়া" tabindex="-1">৬.২ প্রতিকার প্রক্রিয়া <a class="header-anchor" href="#৬-২-প্রতিকার-প্রক্রিয়া" aria-label="Permalink to &quot;৬.২ প্রতিকার প্রক্রিয়া&quot;">​</a></h3><ul><li><strong>বণ্টন আপত্তি</strong>: সম্পদ বণ্টন ফলাফলে আপত্তি আছে এমন ব্যক্তি সম্পদ ন্যায়বিচার কমিটিতে পুনর্বিচারের জন্য আবেদন করতে পারবে</li><li><strong>সম্পদ বিবাদ সালিশ</strong>: সম্পদ বিবাদ অ্যাঙ্কর আদালত দ্বারা সালিশ করা হয়, সালিশের ফলাফল আইনি প্রভাব রাখে</li><li><strong>অত্যাচারিত প্রতিকার</strong>: সম্পদ একচেটিয়াবাদ, সম্পদ লুঠেরবাদ ইত্যাদি আচরণের কারণে ক্ষতিগ্রস্ত ব্যক্তি অ্যাঙ্কর আদালতে মামলা দায়ের করে ক্ষতিপূরণ দাবি করতে পারবে</li><li><strong>জরুরি উদ্ধার</strong>: বিশেষ পরিস্থিতিতে (যেমন বিপর্যয়, যুদ্ধ ইত্যাদি), জরুরি সম্পদ স্থানান্তর প্রক্রিয়া শুরু করা, ক্ষতিগ্রস্ত গোষ্ঠীর মৌলিক সম্পদ চাহিদা নিশ্চিত করা</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সাধনা সম্পদ উন্মুক্তকরণ প্রক্রিয়া হলো অ্যাঙ্কর সিম্বায়োটিক সভ্যতার অর্থনৈতিক ব্যবস্থার মূল অংশ। এটি &quot;মৌলিক নিশ্চয়তা + বেশি পরিশ্রম বেশি লাভ + একচেটিয়াবাদ বিরোধী + টেকসই + উন্মুক্ত স্বচ্ছ&quot; পাঁচটি নীতির মাধ্যমে, একটি ন্যায়সঙ্গত, কার্যকর, টেকসই সম্পদ বণ্টন ব্যবস্থা গঠন করে। সম্পদ উন্মুক্তকরণ প্রক্রিয়ার চূড়ান্ত লক্ষ্য, সমস্ত জীবকে সমান পরিমাণ সম্পদ প্রদান করা নয়, বরং প্রতিটি জীবকে সম্পদ পাওয়ার ন্যায়সঙ্গত সুযোগ দেওয়া, সম্পদকে সবচেয়ে মূল্য সৃষ্টি করতে সক্ষম স্থানে প্রবাহিত করা, এবং টেকসই শর্তে সভ্যতার সম্পদের মোট পরিমাণ ক্রমাগত বৃদ্ধি করা। যখন সাধনা সম্পদ আর কিছু লোকের দখলে থাকা ব্যক্তিগত সম্পত্তি না হয়ে, বরং সর্বজনীনভাবে শেয়ারকৃত, চক্রাকারভাবে বৃদ্ধিপ্রাপ্ত পাবলিক সম্পদ হয়ে যায়, তখন &quot;প্রত্যেকের পথ আছে&quot; এর আদর্শ প্রকৃতপক্ষে বাস্তবায়িত হতে পারে, এবং সর্বজনীন অগ্রগতির লক্ষ্য প্রকৃতপক্ষে বাস্তবায়িত হতে পারে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (বেশি পরিশ্রম বেশি লাভ বণ্টন নীতি)</li><li>08-人人有路保障体系 (প্রত্যেকের পথ আছে নিশ্চয়তা ব্যবস্থা)</li><li>22-资源分配联产承包机制 (সম্পদ বণ্টন যৌথ উৎপাদন চুক্তি প্রক্রিয়া)</li></ul>',57)])])}const c=a(o,[["render",d]]);export{b as __pageData,c as default};
